package io.aetheris.orchestrator.career;import org.springframework.stereotype.Service;import java.util.*;@Service public class RecruiterSimulationService {private final CareerAuditRepository audits;private final List<CareerEvidenceConnector> connectors;public RecruiterSimulationService(CareerAuditRepository audits,Optional<List<CareerEvidenceConnector>> connectors){this.audits=audits;this.connectors=connectors.orElse(List.of());}public RecruiterSimulationResult simulate(RecruiterSimulationRequest r){CareerAuditEntity audit=audits.findById(r.careerAuditId()).orElseThrow(()->new NoSuchElementException("Unknown career audit"));String tier=r.targetCompanyTier()==null||r.targetCompanyTier().isBlank()?"competitive":r.targetCompanyTier().trim();int connectorBonus=(int)connectors.stream().filter(c->c.available()&&c.readOnly()).count()*2;int score=Math.max(0,Math.min(100,(int)Math.round(audit.getReadinessScore()*.72+Math.max(0,Math.min(100,r.interviewScoreHint()))*.28+connectorBonus)));List<String> strengths=new ArrayList<>(),risks=new ArrayList<>(),next=new ArrayList<>();if(audit.getReadinessScore()>=80)strengths.add("Strong verified portfolio/readiness evidence");else{risks.add("Public/project evidence is not yet top-tier");next.add("Close the highest-impact readiness gaps from the latest career audit");}if(r.interviewScoreHint()>=75)strengths.add("Interview preparation signal is competitive");else{risks.add("Interview evidence needs more practice");next.add("Run technical and behavioral recruiter simulations with evidence-backed answers");}String verdict=score>=85?"STRONG_SHORTLIST":score>=70?"COMPETITIVE":score>=55?"BORDERLINE":"NOT_READY";return new RecruiterSimulationResult(audit.getTargetRole(),tier,score,verdict,List.copyOf(strengths),List.copyOf(risks),List.copyOf(next));}public List<Map<String,Object>> connectors(){return connectors.stream().map(c->Map.<String,Object>of("id",c.id(),"readOnly",c.readOnly(),"available",c.available())).toList();}}
